// WrapClientEndpoint wraps the old-style Endpoint (without context) into a new cep.Endpoint.
// This is for backward compatibility during the transition period.
// Deprecated: Use cep.Endpoint directly in new code.
func WrapClientEndpoint(old Endpoint) cep.Endpoint {
	return func(ctx context.Context, req, resp interface{}) error {
		return old(ctx, req, resp)
	}
}

// WrapServerEndpoint wraps the old-style Endpoint (without context) into a new sep.Endpoint.
// This is for backward compatibility during the transition period.
// Deprecated: Use sep.Endpoint directly in new code.
func WrapServerEndpoint(old Endpoint) sep.Endpoint {
	return func(ctx context.Context, req, resp interface{}) error {
		return old(ctx, req, resp)
	}
}

// UnwrapClientEndpoint converts a cep.Endpoint back to the old-style Endpoint.
// This should only be used for compatibility with legacy code.
// Deprecated: Migrate to cep.Endpoint in new code.
func UnwrapClientEndpoint(new cep.Endpoint) Endpoint {
	return func(ctx context.Context, req, resp interface{}) error {
		return new(ctx, req, resp)
	}
}

// UnwrapServerEndpoint converts a sep.Endpoint back to the old-style Endpoint.
// This should only be used for compatibility with legacy code.
// Deprecated: Migrate to sep.Endpoint in new code.
func UnwrapServerEndpoint(new sep.Endpoint) Endpoint {
	return func(ctx context.Context, req, resp interface{}) error {
		return new(ctx, req, resp)
	}
}
