// WithUnaryOptions adds unary-specific options that only apply to non-streaming RPC calls.
// UnaryOptions allow fine-grained control over timeouts, retries, and middleware for unary RPCs.
func WithUnaryOptions(opts ...client.UnaryOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithUnaryOptions(...)")
		o.UnaryOptions = append(o.UnaryOptions, opts...)
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout specifically for unary calls.
// This timeout applies only to non-streaming RPCs and overrides the default timeout.
func WithUnaryRPCTimeout(d time.Duration) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithUnaryRPCTimeout(" + d.String() + ")")
		unaryOpt := func(opts *client.Options) {
			rpcinfo.AsMutableRPCConfig(opts.Configs).SetRPCTimeout(d)
		}
		o.UnaryOptions = append(o.UnaryOptions, unaryOpt)
	}}
}

