// WithStreamOptions applies a list of StreamOption functions to streaming RPC calls.
// These options configure generic streaming behavior (not protocol-specific).
func WithStreamOptions(opts ...StreamOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamOptions(...)")
		o.StreamOptions = append(o.StreamOptions, opts...)
	}}
}

// WithStreamRecvTimeout sets the receive timeout for individual Recv() calls in streaming RPCs.
// This timeout applies per message receive operation, not to the entire stream lifecycle.
func WithStreamRecvTimeout(d time.Duration) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamRecvTimeout(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamXOpts.RecvTimeout = d
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamMiddleware adds streaming middleware that wraps the entire stream lifecycle.
// Middleware is invoked when the stream is created and can intercept all stream operations.
func WithStreamMiddleware(mw streamx.StreamMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamMiddleware(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamXOpts.StreamMWs = append(opts.StreamXOpts.StreamMWs, mw)
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamMiddlewareBuilder adds a stream middleware builder that creates middleware
// based on the stream context. The builder is called when a stream is established.
func WithStreamMiddlewareBuilder(mwb func(ctx streamx.StreamContext) streamx.StreamMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamMiddlewareBuilder(...)")
		streamOpt := func(opts *client.Options) {
			// Store as StreamMiddleware wrapper that applies the builder
			mw := func(next streamx.StreamHandler) streamx.StreamHandler {
				return func(ctx streamx.StreamContext) error {
					dynamicMW := mwb(ctx)
					return dynamicMW(next)(ctx)
				}
			}
			opts.StreamXOpts.StreamMWs = append(opts.StreamXOpts.StreamMWs, mw)
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamRecvMiddleware adds middleware that intercepts individual Recv() operations.
// RecvMiddleware is invoked on every message received from the stream.
func WithStreamRecvMiddleware(mw streamx.StreamRecvMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
