// WithStreamOptions applies a list of StreamOption functions to streaming RPC calls.
// These options configure generic streaming behavior (not protocol-specific).
func WithStreamOptions(opts ...StreamOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamOptions(...)")
		o.StreamOptions = append(o.StreamOptions, opts...)
	}}
}

// WithStreamRecvTimeout sets the receive timeout for individual Recv() calls in streaming RPCs.
// This timeout applies per message receive operation, not to the entire stream lifecycle.
func WithStreamRecvTimeout(d time.Duration) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamRecvTimeout(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamX.RecvTimeout = d
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamMiddleware adds streaming middleware that wraps the entire stream lifecycle.
// Middleware is invoked when the stream is created and can intercept all stream operations.
func WithStreamMiddleware(mw cep.StreamMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamMiddleware(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamX.StreamMWs = append(opts.StreamX.StreamMWs, mw)
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamMiddlewareBuilder adds a stream middleware builder that creates
// per-stream middleware based on the context.
func WithStreamMiddlewareBuilder(mwb cep.StreamMiddlewareBuilder) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamMiddlewareBuilder(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamX.StreamMWBs = append(opts.StreamX.StreamMWBs, mwb)
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamRecvMiddleware adds middleware that intercepts individual Recv() operations.
// RecvMiddleware is invoked on every message received from the stream.
func WithStreamRecvMiddleware(mw cep.StreamRecvMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamRecvMiddleware(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamX.StreamRecvMWs = append(opts.StreamX.StreamRecvMWs, mw)
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamRecvMiddlewareBuilder adds a receive middleware builder that creates
// per-stream middleware based on the context.
func WithStreamRecvMiddlewareBuilder(mwb cep.StreamRecvMiddlewareBuilder) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamRecvMiddlewareBuilder(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamX.StreamRecvMWBs = append(opts.StreamX.StreamRecvMWBs, mwb)
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamSendMiddleware adds middleware that intercepts individual Send() operations.
// SendMiddleware is invoked on every message sent to the stream.
func WithStreamSendMiddleware(mw cep.StreamSendMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamSendMiddleware(...)")
		streamOpt := func(opts *client.Options) {
			opts.StreamX.StreamSendMWs = append(opts.StreamX.StreamSendMWs, mw)
		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithStreamSendMiddlewareBuilder adds a send middleware builder that creates
